190	func (s *mcpServer) sendToolResult(id *json.RawMessage, text string, structured any, isError bool) {
191		res := map[string]any{
192			"content": []map[string]string{
193				{"type": "text", "text": text},
194			},
195		}
196		if structured != nil && !isError {
197			res["structuredContent"] = structured
198		}
199		if isError {
200			res["isError"] = true
201		}
202		s.sendResponse(id, res)
203	}
