223	// UpdateParentIndex ensures the concept is listed in its immediate directory index.md.
224	func UpdateParentIndex(bundleDir string, c *Concept) error {
225		absBundle, err := filepath.Abs(bundleDir)
226		if err != nil {
227			return fmt.Errorf("invalid bundle directory: %w", err)
228		}
229	
230		normConceptPath := strings.ReplaceAll(c.Path, "\\", "/")
231		dir := path.Dir(normConceptPath)
232		indexRelPath := "index.md"
233		if dir != "." {
234			indexRelPath = filepath.Join(filepath.FromSlash(dir), "index.md")
235		}
236	
237		indexPath := filepath.Join(absBundle, filepath.Clean(indexRelPath))
238		rel, err := filepath.Rel(absBundle, indexPath)
239		relSlash := strings.ReplaceAll(rel, "\\", "/")
240		if err != nil || relSlash == ".." || strings.HasPrefix(relSlash, "../") {
241			return fmt.Errorf("path traversal denied: parent index %q escapes bundle directory", indexRelPath)
242		}
243		if _, err := ensureWithinRoot(bundleDir, indexPath); err != nil {
244			return err
245		}
246	
247		return WithBundleLock(bundleDir, func() error {
248			return updateParentIndexLocked(bundleDir, c)
249		})
250	}
