1	package lock
2	
3	import (
4		"bufio"
5		"fmt"
6		"os"
7		"path/filepath"
8		"strings"
9		"time"
10	)
11	
12	type BundleEntry struct {
13		ID          string    `json:"id"`
14		Source      string    `json:"source"`
15		Version     string    `json:"version"`
16		Hash        string    `json:"hash"`
17		InstalledAt time.Time `json:"installed_at"`
18	}
19	
20	type Lockfile struct {
21		Version int           `json:"version"`
22		Bundles []BundleEntry `json:"bundles"`
23	}
24	
25	func (lf *Lockfile) Upsert(entry BundleEntry) {
26		for i, b := range lf.Bundles {
27			if b.ID == entry.ID {
28				lf.Bundles[i] = entry
29				return
30			}
31		}
32		lf.Bundles = append(lf.Bundles, entry)
33	}
34	
35	func (lf *Lockfile) Remove(id string) bool {
36		for i, b := range lf.Bundles {
37			if b.ID == id {
38				lf.Bundles = append(lf.Bundles[:i], lf.Bundles[i+1:]...)
39				return true
40			}
41		}
42		return false
43	}
44	
45	func ReadLockfile(path string) (*Lockfile, error) {
46		cleanPath := filepath.Clean(path)
47		// #nosec G304 -- lockfile path is provided by caller or default workspace okf.lock
48		f, err := os.Open(cleanPath)
49		if err != nil {
50			if os.IsNotExist(err) {
51				return &Lockfile{Version: 1}, nil
52			}
53			return nil, err
54		}
55		defer func() { _ = f.Close() }()
56	
57		lf := &Lockfile{Version: 1}
58		scanner := bufio.NewScanner(f)
59		var current *BundleEntry
60	
61		for scanner.Scan() {
62			line := strings.TrimSpace(scanner.Text())
63			if line == "" || strings.HasPrefix(line, "#") {
64				continue
65			}
66			if strings.HasPrefix(line, "version:") {
67				_, _ = fmt.Sscanf(line, "version: %d", &lf.Version)
68				continue
69			}
70			if strings.HasPrefix(line, "- id:") {
71				if current != nil {
72					lf.Bundles = append(lf.Bundles, *current)
73				}
74				val := strings.TrimSpace(strings.TrimPrefix(line, "- id:"))
75				val = strings.Trim(val, `"'`)
76				current = &BundleEntry{ID: val}
77				continue
78			}
79			if current != nil {
80				parts := strings.SplitN(line, ":", 2)
81				if len(parts) == 2 {
82					k := strings.TrimSpace(parts[0])
83					v := strings.Trim(strings.TrimSpace(parts[1]), `"'`)
84					switch k {
85					case "source":
86						current.Source = v
87					case "version":
88						current.Version = v
89					case "hash":
90						current.Hash = v
91					case "installed_at":
92						t, _ := time.Parse(time.RFC3339, v)
93						current.InstalledAt = t
94					}
95				}
96			}
97		}
98		if current != nil {
99			lf.Bundles = append(lf.Bundles, *current)
100		}
101	
102		return lf, scanner.Err()
103	}
104	
105	func WriteLockfile(path string, lf *Lockfile) error {
106		cleanPath := filepath.Clean(path)
107		// #nosec G304 -- lockfile path is provided by caller or default workspace okf.lock
108		f, err := os.Create(cleanPath)
109		if err != nil {
110			return err
111		}
112		defer func() { _ = f.Close() }()
113	
114		w := bufio.NewWriter(f)
115		if _, err := fmt.Fprintf(w, "# okf.lock - Generated by OKF Agent Memory. DO NOT EDIT MANUALLY.\n"); err != nil {
116			return err
117		}
118		if _, err := fmt.Fprintf(w, "version: %d\n", lf.Version); err != nil {
119			return err
120		}
121		if _, err := fmt.Fprintf(w, "bundles:\n"); err != nil {
122			return err
123		}
124		for _, b := range lf.Bundles {
125			if _, err := fmt.Fprintf(w, "  - id: %q\n", b.ID); err != nil {
126				return err
127			}
128			if _, err := fmt.Fprintf(w, "    source: %q\n", b.Source); err != nil {
129				return err
130			}
131			if _, err := fmt.Fprintf(w, "    version: %q\n", b.Version); err != nil {
132				return err
133			}
134			if _, err := fmt.Fprintf(w, "    hash: %q\n", b.Hash); err != nil {
135				return err
136			}
137			if _, err := fmt.Fprintf(w, "    installed_at: %q\n", b.InstalledAt.UTC().Format(time.RFC3339)); err != nil {
138				return err
139			}
140		}
141		return w.Flush()
142	}
