8	// IsAbsPath securely checks if a path is absolute across platforms, preventing
9	// path traversal evasion where Windows paths (e.g., C:\) are evaluated on POSIX,
10	// or POSIX paths (e.g., /etc) are evaluated on Windows.
11	func IsAbsPath(path string) bool {
12		if filepath.IsAbs(path) {
13			return true
14		}
15		if strings.HasPrefix(path, "/") || strings.HasPrefix(path, "\\") {
16			return true
17		}
18		if len(path) >= 2 && path[1] == ':' && ((path[0] >= 'a' && path[0] <= 'z') || (path[0] >= 'A' && path[0] <= 'Z')) {
19			return true
20		}
21		return false
22	}
